        st.one_of(st.integers(0, 3), st.just(MOD - 1), st.integers(0, MOD - 1)),
        min_size=H * W, max_size=H * W))
    Q = draw(st.integers(1, 5))
    sh = draw(st.integers(1, H))
    sw = draw(st.integers(1, W))
